const hospitalityItems = [
  {
    id: "mai-house",
    titleKey: "hospitality.card1.title",
    descKey: "hospitality.card1.desc",
    embed: "https://mai-house-website.pages.dev/"
  },
  {
    id: "oakwood",
    titleKey: "hospitality.card2.title",
    descKey: "hospitality.card2.desc",
    embed: "https://oakwood-richlane-residence.pages.dev/"
  },
  {
    id: "hong-home",
    titleKey: "hospitality.card3.title",
    descKey: "hospitality.card3.desc",
    embed: "https://honghome.pages.dev/"
  }
];

export default function HomePage() {
  const [lang, setLang] = useState("en");
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [fnbItems, setFnbItems] = useState([]);

  useEffect(() => {
    const saved = window.localStorage.getItem("lang");
    const browserLang = (navigator.language || "").toLowerCase();
    const defaultLang = saved || (browserLang.startsWith("vi") ? "vi" : "en");
    setLang(defaultLang);
  }, []);

  useEffect(() => {
    const loadItems = async () => {
      try {
        const response = await fetch("/api/fnb", { cache: "no-store" });
        const data = await response.json();
        setFnbItems(Array.isArray(data) ? data : data.items || []);
      } catch (error) {
        setFnbItems([]);
      }
    };

    loadItems();
  }, []);

  useEffect(() => {
    window.localStorage.setItem("lang", lang);
    document.documentElement.lang = lang;
    document.title =
      translations[lang]?.["meta.title"] || translations.en["meta.title"];
  }, [lang]);

  const t = useMemo(() => translations[lang] || translations.en, [lang]);

  return (
    <>
      <nav>
        <a href="/" className="logo">
          RV MEDIA
        </a>
        <div className="nav-links">
          <a href="#tours-fnb">{t["nav.commercial"]}</a>
          <a href="#tours-hospitality">{t["nav.hospitality"]}</a>
          <a href="#about">{t["nav.contact"]}</a>
          <a href="/admin">{t["nav.admin"]}</a>
        </div>
        <div className="lang-switch">
          <select
            id="languageSelect"
            className="lang-select"
            aria-label="Language"
            value={lang}
            onChange={(event) => setLang(event.target.value)}
          >
            <option value="en">{t["lang.en"]}</option>
            <option value="vi">{t["lang.vi"]}</option>
          </select>
        </div>
      </nav>

      <header className="hero">
        <h1
          dangerouslySetInnerHTML={{
            __html: t["hero.title"]
          }}
        />
        <p>{t["hero.subtitle"]}</p>
        <button onClick={() => setIsModalOpen(true)} className="btn">
          {t["hero.cta"]}
        </button>
      </header>

      <section id="tours-fnb" className="section">
        <div className="section-title">
          <h2>{t["fnb.title"]}</h2>
          <p>{t["fnb.subtitle"]}</p>
          <div className="section-action">
            <a href="/fnb" className="btn btn-small">
              {t["fnb.folderCta"]}
            </a>
          </div>
        </div>

        <div className="grid-container">
          {fnbItems.map((item) => (
            <div className="card" key={item.id}>
              <iframe src={item.embed} allowFullScreen loading="lazy" />
              <div className="card-body">
                <h3>{item.title?.[lang] || item.title?.en}</h3>
                <p>{item.description?.[lang] || item.description?.en}</p>
              </div>
            </div>
          ))}
        </div>
      </section>

      <section
        id="tours-hospitality"
        className="section"
        style={{ backgroundColor: "#0f1216" }}
      >
        <div className="section-title">
          <h2>{t["hospitality.title"]}</h2>
          <p>{t["hospitality.subtitle"]}</p>
        </div>

        <div className="grid-container">
          {hospitalityItems.map((item) => (
            <div className="card" key={item.id}>
              <iframe src={item.embed} allowFullScreen loading="lazy" />
              <div className="card-body">
                <h3>{t[item.titleKey]}</h3>
                <p>{t[item.descKey]}</p>
              </div>
            </div>
          ))}
        </div>
      </section>

      <section id="about" className="section">
        <div className="about-grid">
          <div className="contact-text">
            <h2>{t["about.title"]}</h2>
            <p style={{ marginBottom: "20px" }}>{t["about.body"]}</p>
            <p
              dangerouslySetInnerHTML={{
                __html: t["about.highlight"]
              }}
            />
          </div>

          <div className="contact-box">
            <div className="contact-item">
              <span className="icon-box">✉️</span>
              <div>
                <strong>{t["contact.emailLabel"]}</strong>
                <br />
                <a
                  href="mailto:contact@rvmedia.vn"
                  style={{
                    color: "var(--text-main)",
                    textDecoration: "none",
                    transition: "0.3s"
                  }}
                >
                  contact@rvmedia.vn
                </a>
              </div>
            </div>

            <div className="contact-item">
              <span className="icon-box">📞</span>
              <div>
                <strong>{t["contact.phoneLabel"]}</strong>
                <br />
                <a
                  href="tel:0966888782"
                  style={{
                    color: "var(--gold)",
                    fontSize: "1.2rem",
                    fontWeight: "bold",
                    textDecoration: "none"
                  }}
                >
                  0966 888 782
                </a>
                <br />
                <a
                  href="https://zalo.me/0966888782"
                  target="_blank"
                  rel="noreferrer"
                  style={{
                    fontSize: "0.85rem",
                    background: "var(--gold)",
                    padding: "4px 10px",
                    borderRadius: "4px",
                    color: "black",
                    textDecoration: "none",
                    fontWeight: "bold",
                    display: "inline-block",
                    marginTop: "8px"
                  }}
                >
                  {t["contact.zaloCta"]}
                </a>
              </div>
            </div>

            <button
              onClick={() => setIsModalOpen(true)}
              className="btn btn-filled"
              style={{
                width: "100%",
                display: "block",
                cursor: "pointer",
                border: "none",
                fontSize: "1rem"
              }}
            >
              {t["contact.cta"]}
            </button>
          </div>
        </div>
      </section>

      {isModalOpen ? (
        <div className="modal-overlay" onClick={() => setIsModalOpen(false)}>
          <div className="modal-content" onClick={(event) => event.stopPropagation()}>
            <span className="close-btn" onClick={() => setIsModalOpen(false)}>
              ×
            </span>
            <h2 style={{ marginBottom: "10px" }}>{t["modal.title"]}</h2>
            <p style={{ fontSize: "0.9rem", marginBottom: "25px" }}>
              {t["modal.subtitle"]}
            </p>

            <form
              action="mailto:contact@rvmedia.vn"
              method="post"
              encType="text/plain"
            >
              <div className="form-group">
                <label>{t["modal.nameLabel"]}</label>
                <input
                  type="text"
                  name="name"
                  placeholder={t["modal.namePlaceholder"]}
                  required
                />
              </div>
              <div className="form-group">
                <label>{t["modal.phoneLabel"]}</label>
                <input
                  type="tel"
                  name="phone"
                  placeholder={t["modal.phonePlaceholder"]}
                  required
                />
              </div>
              <div className="form-group">
                <label>{t["modal.serviceLabel"]}</label>
                <select name="type">
                  <option>{t["modal.service1"]}</option>
                  <option>{t["modal.service2"]}</option>
                  <option>{t["modal.service3"]}</option>
                  <option>{t["modal.service4"]}</option>
                </select>
              </div>
              <button
                type="submit"
                className="btn btn-filled"
                style={{ width: "100%", border: "none" }}
              >
                {t["modal.submit"]}
              </button>
            </form>
          </div>
        </div>
      ) : null}

      <footer>
        <p>{t["footer.rights"]}</p>
      </footer>
    </>
  );
}
